import React, { useState, useEffect } from 'react';
import MapComponent from './MapComponent';

const LocationPicker = ({ 
  initialLatitude = 48.8566, 
  initialLongitude = 2.3522,
  city = "Paris",
  onLocationSelected 
}) => {
  const [latitude, setLatitude] = useState(initialLatitude);
  const [longitude, setLongitude] = useState(initialLongitude);
  const [searchQuery, setSearchQuery] = useState(city);

  const geocodeCity = async (cityName) => {
    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(cityName)}&limit=1`
      );
      const data = await response.json();
      
      if (data && data.length > 0) {
        const newLat = parseFloat(data[0].lat);
        const newLon = parseFloat(data[0].lon);
        setLatitude(newLat);
        setLongitude(newLon);
        
        if (onLocationSelected) {
          onLocationSelected(newLat, newLon);
        }
        
        return { lat: newLat, lon: newLon };
      }
    } catch (error) {
      console.error('Erreur géocodage:', error);
    }
    return null;
  };

  useEffect(() => {
    if (city) {
      geocodeCity(city);
    }
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      geocodeCity(searchQuery);
    }
  };

  const handleMapPositionChange = (lat, lng) => {
    setLatitude(lat);
    setLongitude(lng);
    if (onLocationSelected) {
      onLocationSelected(lat, lng);
    }
  };

  return (
    <div className="location-picker">
      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3>📍 Localisation de la salle</h3>
        
        <div className="form-group">
          <label className="form-label">Rechercher une ville</label>
          <div className="search-bar" style={{ display: 'flex', gap: '0.5rem' }}>
            <input
              type="text"
              className="form-input"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Ex: Paris, Lyon, Marseille..."
              style={{ flex: 1 }}
            />
            <button 
              onClick={handleSearch}
              className="btn btn-primary"
            >
              Rechercher
            </button>
          </div>
        </div>

        <div className="coordinates" style={{ 
          backgroundColor: '#f8f9fa', 
          padding: '1rem', 
          borderRadius: '4px',
          marginTop: '1rem'
        }}>
          <p><strong>Coordonnées GPS :</strong></p>
          <p>Latitude: <code>{latitude.toFixed(6)}</code></p>
          <p>Longitude: <code>{longitude.toFixed(6)}</code></p>
          <small style={{ color: '#666' }}>
            Déplacez le marqueur sur la carte pour préciser l'emplacement exact
          </small>
        </div>
      </div>

      <div className="card">
        <MapComponent
          latitude={latitude}
          longitude={longitude}
          zoom={15}
          markerText="Emplacement de la salle"
          draggable={true}
          onPositionChange={handleMapPositionChange}
          height="400px"
        />
      </div>
    </div>
  );
};

export default LocationPicker;
